private List<TimelineObjectHolder<VersionType, ObjectType>> lookup(Interval interval, Partitions completeness)
{
  List<TimelineObjectHolder<VersionType, ObjectType>> retVal = new ArrayList<>();
  NavigableMap<Interval, TimelineEntry> timeline;
  if (completeness == Partitions.INCOMPLETE_OK) {
    timeline = incompletePartitionsTimeline;
  } else {
    timeline = completePartitionsTimeline;
  }

  final boolean queryIsEternity = Intervals.isEternity(interval);
  final boolean queryEndpointsComparable = Intervals.canCompareEndpointsAsStrings(interval);
  final long queryStartMillis = interval.getStartMillis();
  final long queryEndMillis = interval.getEndMillis();

  if (timeline.isEmpty()) {
    return retVal;
  }

  Interval[] timelineKeys = timeline.keySet().toArray(new Interval[0]);
  if (Intervals.findOverlappingInterval(interval, timelineKeys) == null) {
    return retVal;
  }

  for (Entry<Interval, TimelineEntry> entry : timeline.entrySet()) {
    Interval timelineInterval = entry.getKey();
    TimelineEntry val = entry.getValue();
    long timelineStartMillis = timelineInterval.getStartMillis();
    long timelineEndMillis = timelineInterval.getEndMillis();

    if (timelineEndMillis <= queryStartMillis) {
      continue;
